-- Generated by tools/generate.py from bricksurance-data-core model v0.11.0.
-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_policy_lifecycle.lifecycle_metrics
COMMENT 'Flow KPIs over the policy event spine - new business, renewals, lapses, cancellations and mid-term adjustments by line, period, channel and actor. Retention is chain-based (renewed over invited). Point-in-time policies-in-force is answered from vw_policy_current (status = IN_FORCE), not here. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_policy_lifecycle.policy_event

joins:
  - name: policy
    source: lr_serverless_aws_us_catalog.bricksurance_policy.policy
    on: source.policy_id = policy.policy_id

dimensions:
  - name: policy_event_type_code
    expr: source.policy_event_type_code
  - name: line_of_business_code
    expr: policy.line_of_business_code
  - name: event_month
    expr: DATE_TRUNC('MONTH', source.event_ts)
  - name: actor_type_code
    expr: source.actor_type_code
  - name: event_source_system_code
    expr: source.event_source_system_code

measures:
  - name: event_count
    expr: COUNT(event_id)
  - name: new_business_count
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code = 'BOUND' THEN policy_id END)
  - name: renewal_invited_count
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code = 'RENEWAL_INVITED' THEN policy_id END)
  - name: renewed_count
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code = 'RENEWED' THEN policy_id END)
  - name: lapsed_count
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code = 'LAPSED' THEN policy_id END)
  - name: cancelled_count
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code IN ('CANCELLED_INSURED', 'CANCELLED_INSURER', 'CANCELLED_NONPAYMENT') THEN policy_id END)
  - name: mta_count
    expr: COUNT(CASE WHEN policy_event_type_code = 'MTA_APPLIED' THEN event_id END)
  - name: retention_rate
    expr: COUNT(DISTINCT CASE WHEN policy_event_type_code = 'RENEWED' THEN policy_id END) / NULLIF(COUNT(DISTINCT CASE WHEN policy_event_type_code = 'RENEWAL_INVITED' THEN policy_id END), 0)
$$;
